PROGRAM Blinky
VAR_OUTPUT LED_Output AT %Q0.0 : BOOL; END_VAR
VAR OffTimer : TON; OnTimer : TON; State : BOOL := FALSE; END_VAR
OffTimer(IN := NOT State, PT := T#500ms);
OnTimer(IN := State, PT := T#500ms);
IF OffTimer.Q THEN State := TRUE; END_IF;
IF OnTimer.Q THEN State := FALSE; END_IF;
LED_Output := State;
END_PROGRAM

PROGRAM Blinky
VAR_OUTPUT LED_Output AT %Q0.0 : BOOL; END_VAR
VAR BlinkTimer : TON; LedState : BOOL := FALSE; END_VAR
BlinkTimer(IN := TRUE, PT := T#500ms);
IF BlinkTimer.Q THEN LedState := NOT LedState; BlinkTimer(IN := FALSE, PT := T#500ms); END_IF;
LED_Output := LedState;
END_PROGRAM

PROGRAM Blinky
VAR_OUTPUT LED_Output AT %Q0.0 : BOOL; END_VAR
VAR Scans : INT := 0; END_VAR
Scans := Scans + 1;
IF Scans >= 100 THEN Scans := 0; END_IF;
LED_Output := Scans >= 50;
END_PROGRAM

PROGRAM Blinky
VAR_OUTPUT LED_Output AT %Q0.0 : BOOL; END_VAR
VAR Timer : TON; State : BOOL := FALSE; END_VAR
Timer(IN := TRUE, PT := T#250ms);
IF Timer.Q THEN State := NOT State; Timer(IN := FALSE, PT := T#250ms); END_IF;
LED_Output := State;
END_PROGRAM

PROGRAM Blinky
VAR_OUTPUT LED_Output AT %Q0.0 : BOOL; END_VAR
VAR Scans : INT := 0; END_VAR
Scans := Scans + 1;
IF Scans >= 50 THEN Scans := 0; END_IF;
LED_Output := Scans < 10;
END_PROGRAM
